package com.vajjha.recipes.config;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.Configuration;import org.springframework.web.servlet.config.annotation.*;@Configuration public class WebConfig implements WebMvcConfigurer{@Value("${app.cors.allowed-origin:http://localhost:5173}")private String origin;@Override public void addCorsMappings(CorsRegistry r){r.addMapping("/api/**").allowedOrigins(origin).allowedMethods("GET","POST","PUT","PATCH","DELETE","OPTIONS").allowedHeaders("Content-Type","X-APP-KEY").maxAge(3600);}}